import { APPS, setPendingParams } from '../config/apps'

export default function Navigate({ $router, $storex }) {

  // ════════════════════════════════════════════════════════════════
  // PROJECT BASE PATH HELPERS
  // Routes are mounted under the escaped active project name, e.g.
  //   /codx-junior/chats   /my.project/desktop   /my-project/settings
  // ════════════════════════════════════════════════════════════════

  function activeProjectSegment() {
    const name = $storex.projects.activeProject?.project_name || ''
    return encodeURIComponent(name)
  }

  // Location for the project-scoped home, or the unscoped root while no
  // project is active yet (the guard/store scope it once one loads).
  function homeLocation() {
    const projectName = activeProjectSegment()
    return projectName
      ? { name: 'home', params: { projectName } }
      : { name: 'root' }
  }

  // ════════════════════════════════════════════════════════════════
  // ROUTE BUILDERS - Centralized route path generation
  // ════════════════════════════════════════════════════════════════

  const routes = {
    chat: {
      list: () => ({ name: 'chats' }),
      open: (chatId, chatName) => ({
        name: 'chat',
        params: { chatId, chatName }
      }),
      openWithWorkspace: (chatId, chatName, workspaceId, workspaceName) => ({
        name: 'chat-workspace',
        params: { chatId, chatName, workspaceId, workspaceName }
      })
    },
    meet: {
      list: () => ({ name: 'meet' }),
      open: (meetId) => ({
        name: 'meet-session',
        params: { meetId }
      })
    },
    workspace: {
      list: () => ({ name: 'workspaces' }),
      open: (workspaceId, workspaceName) => ({
        name: 'workspace',
        params: { workspaceId, workspaceName }
      })
    },
    browser: {
      list: () => ({ name: 'browsers' }),
      open: (sessionId, sessionName) => ({
        name: 'browser-session',
        params: { sessionId, sessionName }
      })
    },
    kanban: {
      open: () => ({ name: 'kanban' }),
      // Opens the Task Manager directly on the Planning view
      planning: () => ({ name: 'kanban', query: { view: 'planning' } })
    },
    messenger: {
      open: () => ({ name: 'messenger' })
    },
    desktop: {
      open: () => ({ name: 'codx-junior-split' })
    },
    mobile: {
      open: () => ({ name: 'mobile' })
    },
    home: {
      open: () => homeLocation()
    }
  }

  // ════════════════════════════════════════════════════════════════
  // UNIFIED APP OPENER
  // The single place that decides between a desktop panel and a mobile
  // route. Everything else (UI store openers, launchers) funnels here.
  // ════════════════════════════════════════════════════════════════

  function openApp(appKey, payload = {}) {
    const def = APPS[appKey]

    if (!def) {
      console.warn(`[Navigation] openApp: unknown app "${appKey}"`)
      return
    }

    const params = def.desktopParams ? def.desktopParams(payload) : (payload.params || {})

    // ── Mobile / router mode → one route per app ──────────────────
    if ($storex.ui.isMobile) {
      setPendingParams(def.id, params)
      // The project prefix is injected centrally by the router's push wrapper.
      $router.push(def.route(payload))
      return
    }

    // ── Desktop / expert mode → one dockview panel per app ────────
    const key = def.desktopKey ? def.desktopKey(payload) : appKey
    const tabId = def.desktopTabId ? def.desktopTabId(payload) : payload.tabId

    $storex.ui.showApp({
      key,
      tabId,
      name: payload.name || def.title,
      component: def.component,
      params
    })
  }

  // ════════════════════════════════════════════════════════════════
  // STATE GETTERS
  // ════════════════════════════════════════════════════════════════

  const $navigation = {
    get activeProject() {
      return $storex.projects.activeProject
    },

    get isDesktopMode() {
      return $router.currentRoute.value.name === 'codx-junior-split'
    },

    get isMobileMode() {
      return $router.currentRoute.value.name === 'mobile'
    },

    get isChatView() {
      const name = $router.currentRoute.value.name
      return name === 'chat' || name === 'chat-workspace'
    },

    get isMeetView() {
      const name = $router.currentRoute.value.name
      return name === 'meet' || name === 'meet-session'
    },

    get isWorkspaceView() {
      const name = $router.currentRoute.value.name
      return name === 'workspace' || name === 'workspaces'
    },

    get isBrowserView() {
      const name = $router.currentRoute.value.name
      return name === 'browsers' || name === 'browser-session'
    },

    get isKanbanView() {
      return $router.currentRoute.value.name === 'kanban'
    },

    get isMessengerView() {
      return $router.currentRoute.value.name === 'messenger'
    },

    get isHomeView() {
      const name = $router.currentRoute.value.name
      return name === 'home' || name === 'root'
    },

    getProjectName() {
      return $storex.projects.activeProject?.project_name || null
    },

    getCurrentRoute() {
      return $router.currentRoute.value
    },

    getChatId() {
      return $router.currentRoute.value.params.chatId || null
    },

    getChatName() {
      return $router.currentRoute.value.params.chatName || null
    },

    getMeetId() {
      return $router.currentRoute.value.params.meetId || null
    },

    getWorkspaceId() {
      return $router.currentRoute.value.params.workspaceId || null
    },

    getWorkspaceName() {
      return $router.currentRoute.value.params.workspaceName || null
    },

    getSessionId() {
      return $router.currentRoute.value.params.sessionId || null
    },

    getSessionName() {
      return $router.currentRoute.value.params.sessionName || null
    },

    get hasChatContext() {
      return this.getChatId() !== null
    },

    get hasMeetContext() {
      return this.getMeetId() !== null
    },

    get hasWorkspaceContext() {
      return this.getWorkspaceId() !== null
    },

    get hasSessionContext() {
      return this.getSessionId() !== null
    },

    // ════════════════════════════════════════════════════════════════
    // INITIALIZATION
    // ════════════════════════════════════════════════════════════════

    init() {
      // Initialize history state on first load
      if (window.history.length === 1) {
        window.history.replaceState(null, '', '/')
        window.history.pushState(null, '', window.location.href)
      }
    },

    async onRouteChanged({ from, to }) {
      // ── OAuth callback ────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return homeLocation()
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return homeLocation()
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return homeLocation()
        }
      }

      // ── Unscoped root → project-scoped home ───────────────────────
      if (to.name === 'root') {
        const projectName = activeProjectSegment()
        if (projectName) {
          return { name: 'home', params: { projectName }, replace: true }
        }
        return true
      }

      // ── Standalone routes with name (opt-out of mobile/desktop redirect) ─
      if (!!to.name) {
        return true
      }

      // ── Mobile redirect ──────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ─────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { ...homeLocation(), replace: true }
      }

      return true
    },

    // ════════════════════════════════════════════════════════════════
    // UNIFIED APP OPEN (exposed to the UI store & components)
    // ════════════════════════════════════════════════════════════════

    openApp,

    // ════════════════════════════════════════════════════════════════
    // CHAT NAVIGATION
    // ════════════════════════════════════════════════════════════════

    chats: {
      list() {
        $router.push(routes.chat.list())
      },

      open(chatId, chatName) {
        if (!chatId) {
          console.warn('[Navigation] chats.open: invalid chatId', chatId)
          return
        }

        const name = chatName || `chat-${chatId}`
        openApp('chat', {
          chat: {
            id: chatId,
            name,
            owner_project_id: $navigation.activeProject?.project_id
          }
        })
      },

      openWithWorkspace(chatId, chatName, workspaceId, workspaceName) {
        if (!chatId || !workspaceId) {
          console.warn('[Navigation] chats.openWithWorkspace: invalid chat or workspace', { chatId, workspaceId })
          return
        }

        openApp('chat', {
          chat: {
            id: chatId,
            name: chatName || `chat-${chatId}`,
            owner_project_id: $navigation.activeProject?.project_id
          },
          workspace: {
            id: workspaceId,
            name: workspaceName || `workspace-${workspaceId}`
          }
        })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // MEET NAVIGATION
    // ════════════════════════════════════════════════════════════════

    meets: {
      list() {
        openApp('meet', {})
      },

      open(meetId) {
        if (!meetId) {
          console.warn('[Navigation] meets.open: invalid meetId', meetId)
          return
        }
        openApp('meet', { meetId })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE NAVIGATION
    // ════════════════════════════════════════════════════════════════

    workspaces: {
      list() {
        openApp('workspaces')
      },

      open(workspaceOrId, workspaceName) {
        // Accept either a full workspace object (preferred: it carries name,
        // path and any other metadata) or a legacy (id, name) pair.
        const workspace = (workspaceOrId && typeof workspaceOrId === 'object')
          ? workspaceOrId
          : { key: workspaceOrId, name: workspaceName }

        if (!workspace?.key) {
          console.warn('[Navigation] workspaces.open: invalid workspace', workspaceOrId)
          return
        }

        const name = workspace.name || `workspace-${workspace.key}`

        // Check if currently in chat view
        if ($navigation.isChatView) {
          const chatId = $navigation.getChatId()
          const chatName = $navigation.getChatName()

          if (chatId) {
            $navigation.chats.openWithWorkspace(chatId, chatName, workspace.key, name)
            return
          }
        }

        // Forward the whole workspace under the `workspace` key (same
        // convention as `chat`) so name/path reach the panel params.
        openApp('workspace', { workspace })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // BROWSER NAVIGATION
    // ════════════════════════════════════════════════════════════════

    browsers: {
      list() {
        openApp('browser-sessions')
      },

      open(sessionId, sessionName) {
        if (!sessionId) {
          console.warn('[Navigation] browsers.open: invalid sessionId', sessionId)
          return
        }

        const name = sessionName || `session-${sessionId}`
        const location = $storex.ui.isMobile
          ? routes.browser.open(sessionId, name)
          : null

        if (location) {
          $router.push(location)
          return
        }

        $storex.ui.showApp({
          tabId: `browser-${sessionId}`,
          name,
          component: 'browser-viewer',
          params: {
            sessionId,
            session: { id: sessionId, name }
          }
        })
      }
    },

    // ════════════════════════════════════════════════════════════════
    // PRIMARY APP NAVIGATION
    // ════════════════════════════════════════════════════════════════

    apps: {
      // Generic entry point – used by the UI store (setActiveTab, openers…)
      openApp,

      openHome() {
        $router.push(routes.home.open())
      },

      openDesktop() {
        $router.push(routes.desktop.open())
      },

      openMessenger() {
        openApp('messenger')
      },

      openMeet(meetId) {
        openApp('meet', { meetId })
      },

      openKanban() {
        openApp('tasks')
      },

      // Open the Task Manager directly on the Planning view
      openPlanning() {
        openApp('planning')
      },

      openMobile() {
        $router.push(routes.mobile.open())
      },

      openFileExplorer() {
        openApp('file-explorer')
      },

      openWiki() {
        openApp('wiki')
      },

      openTeam() {
        openApp('team')
      },

      openViews() {
        console.warn('[Navigation] openViews: no Views route yet')
      },

      openProfiles() {
        openApp('profiles')
      },

      openKnowledge() {
        openApp('knowledge')
      },

      openAnalytics() {
        openApp('analytics')
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    workspace: {
      getCurrentWorkspace() {
        const workspaceId = $navigation.getWorkspaceId()
        const workspaceName = $navigation.getWorkspaceName()

        if (workspaceId) {
          return { id: workspaceId, name: workspaceName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasWorkspaceContext
      }
    },

    // ════════════════════════════════════════════════════════════════
    // SESSION CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    session: {
      getCurrentSession() {
        const sessionId = $navigation.getSessionId()
        const sessionName = $navigation.getSessionName()

        if (sessionId) {
          return { id: sessionId, name: sessionName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasSessionContext
      }
    }
  }

  return $navigation
}

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'
import moment from 'moment'

export const namespaced = true

export const state = () => ({
  showCoder: false,
  showBrowser: false,
  lastActiveTab: "",
  codxJuniorWidth: 30,
  isMobile: false,
  orientation: 'portrait',
  openedFile: null,
  showLogs: false,
  voiceLanguage: 'en-US',
  voiceLanguages: {
    "en-US": "English",
    "es-SP": "Español"
  },
  viewMode: 'expert',
  openApps: {},
  appDivided: 'horizontal',
  resolution: API.screen.display?.resolution,
  resolutions: API.screen.display?.resolutions,
  monitor: "preview",
  monitors: {
    "preview": "CODX-SCREEN-PREVIEW",
    "shared": "CODX-SCREEN-SHARED"
  },
  colorsMap: {},
  coderProjectCodxPath: null,
  uiReady: false,
  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null,
  viewEditor: null,
  activeTeam: null,
  teamBarCollapsed: false,
  panelWidths: {
    chat: 30,
    changes: 33,
    preview: 37
  },
  sidebarCollapsed: false,
  projectLoadingState: {
    isLoading: false,
    projectName: '',
    currentStep: null,
    error: null
  },
  // Call device preferences
  callDevicePreferences: {
    microphone: 'default',
    speaker: 'default',
    autoMute: false
  },
  // Active call panel on chat
  activeChatCallPanelWidth: 30
})

export const getters = getterTree(state, {
  isLandscape: state => state.orientation !== 'portrait',
  monitorToken: state => state.monitors[state.monitor],
  isSharedScreen: () => window.location.pathname === '/shared',
  enableFileManger: () => API.globalSettings?.enable_file_manager,
  activeApps: () => Object.values($storex.ui.openApps),
  isVibeMode: state => state.viewMode === 'vibe',
  isExpertMode: state => state.viewMode === 'expert',
  isDesktopMode: () => $storex.$router.currentRoute.value.name === 'codx-junior-split',
})

export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'

    // Home is not an app: it clears the active app on desktop and is just a
    // route on mobile.
    if (tab === 'home') {
      state.activeTab = null
      state.activeApp = null
      if (state.isMobile) {
        $storex.ui.openApp('home')
      }
      $storex.ui.saveState()
      return
    }

    // Unified opener: every other tab goes through openApp so the same key
    // works on both modes (dockview panel on desktop, route on mobile),
    // including aliased apps such as 'planning' → tasks panel w/ planning view.
    state.activeTab = tab
    $storex.ui.openApp(tab)
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    // setActiveTab now resolves the correct panel/route for any mode.
    $storex.ui.setActiveTab(tab)
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.openApp('log-viewer')
  },
  openChatLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.openApp('chat-logs')
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setVibeMode(state) {
    state.viewMode = 'vibe'
    $storex.ui.saveState()
  },
  setExpertMode(state) {
    state.viewMode = 'expert'
    $storex.ui.saveState()
  },
  setViewMode(state, mode) {
    state.viewMode = mode
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("HH:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("HH:mm:ss"),
      text,
      type: type || 'info'
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  clearNotifications(state, notifications) {
    state.notifications = state.notifications.filter(n => !notifications.includes(n))
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  resetOpenApps(state) {
    state.openApps = {}
    state.activeApp = null
  },
  showApp(state, app) {
    app.tabId = app.tabId || `${app.key || app.name}-${Date.now()}`
    app.params = app.params || {}
    // Auto-inject project_id if not present
    if (!app.params.project_id && $storex.projects.activeProject?.project_id) {
      app.params.project_id = $storex.projects.activeProject.project_id
    }
    app.initialParams = app.initialParams || JSON.parse(JSON.stringify(app.params))
    app.openedAt = Date.now()

    if (state.viewMode !== 'vibe' && !state.isMobile) {
      // Check if app already exists in openApps state
      const existingApp = Object.values(state.openApps).find(openApp => {
        if (app.key && openApp.key) {
          return openApp.key === app.key
        }
        return openApp.component === app.component &&
              JSON.stringify(openApp.initialParams) === JSON.stringify(app.initialParams)
      })

      if (existingApp) {
        state.activeApp = existingApp
        $storex.views.activatePanel(existingApp.tabId)
        return
      }

      // Check if panel already exists in Desktop API by checking component and initialParams
      const desktopApi = $storex.views._desktopApi
      if (desktopApi && desktopApi.panels) {
        const existingPanel = desktopApi.panels.find(panel => {
          if (app.key && panel.key) {
            return panel.key === app.key
          }
          const panelParams = panel.params?.params || panel.params || {}
          return panel.component === app.component &&
                JSON.stringify(panelParams.initialParams || panelParams) === JSON.stringify(app.initialParams)
        })

        if (existingPanel) {
          state.activeApp = app
          $storex.views.activatePanel(existingPanel.id)
          return
        }
      }
    }

    state.openApps = {
      ...state.openApps,
      [app.tabId]: app
    }
    state.activeApp = app
  },
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      const remainingApps = Object.values(state.openApps)
      if (remainingApps.length > 0) {
        state.activeApp = remainingApps.reduce((latest, current) =>
          current.openedAt > latest.openedAt ? current : latest
        )
      } else {
        state.activeApp = null
      }
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'tasks')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  setSidebarCollapsed(state, collapsed) {
    state.sidebarCollapsed = collapsed
    $storex.ui.saveState()
  },
  openChat(_, chat) {
    // Unified: panel on desktop, route on mobile
    $storex.ui.openApp({ appKey: 'chat', payload: { chat } })
  },
  openFileInViewer(_, filePath) {
    $storex.ui.openApp({ appKey: 'file-viewer', payload: { filePath } })
  },
  openViewEditor(state, view = null) {
