    route: () => ({ name: 'vibe-coding' })
  }
}

export function isKnownApp(appKey) {
  return !!APPS[appKey]
}

export default APPS
```

---

## 🛡 Optional hardening — tolerate both keys in `Tab.vue`

`Tab.vue` and `AppWindow.vue` already read `workspace` first, so the registry fix alone repairs them. To make `Tab.vue` resilient to **either** payload shape (matching `AppWindow`'s fallback pattern) and null-safe, apply this:

### `src/components/desktop/Tab.vue`

```vue src/components/desktop/Tab.vue
<script setup>
import AppIcon from '../apps/AppIcon.vue'
</script>
<template>
  <div
    class="codx-tab flex gap-1 items-center justify-between px-1 py-0.5 border rounded-xl w-40 text-md"
    :draggable="!!chat"
    :class="{ 'cursor-grab active:cursor-grabbing': !!chat }"
    @dragstart="onDragStart"
  >
    <div class="w-4/5 flex gap-1 items-center truncate overflow-hidden">
      <!-- Pass loading state to AppIcon so it shows the ring inside the icon area -->
      <AppIcon :app="app || workspace" :loading="isUpdating" />
      <div class="grow truncate overflow-hidden">{{ tabName }}</div>
    </div>
    <div class="click hover:text-warning shrink-0 mr-2" @click="onClose">
      <i class="fa-solid fa-xmark fa-sm"></i>
    </div>
  </div>
</template>
<script>

export default {
  props: ['params'],
  data() {
    return {
      project: null,
    }
  },
  async created() {
    this.project = this.$projects.allProjectsById[this.projectId]
  },
  computed: {
    chat() {
      const chatId = this.params?.params?.chat?.id
      return this.$storex.chats.chats[chatId]
    },
    // Workspace panels carry the raw workspace (name, path, …) in params under
    // the `workspace` key; fall back to the legacy `app` slot for old payloads.
    workspace() {
      return this.params?.params?.workspace || this.params?.params?.app
    },
    app() {
      return this.params?.params?.app
    },
    tabName() {
      return this.chat?.name ||
        this.workspace?.name ||
        this.workspace?.title ||
        this.app?.title ||
        this.params?.params?.tabName
    },
    api() {
      return this.params.api
    },
    containerApi() {
      return this.params.containerApi
    },
    panel() {
      return this.api.panel
    },
    projectId() {
      return this.params?.params?.project_id
    },
    isUpdating() {
      return this.$storex.chats.isChatUpdating(this.chat?.id)
    }
  },
  methods: {
    onDragStart(event) {
      // Only register a sprint task id when the tab is backed by a chat
      if (!this.chat) return
      event.dataTransfer.setData('sprintTaskId', this.chat.id)
      event.dataTransfer.effectAllowed = 'move'
    },
    onClose() {
      this.containerApi.removePanel(this.panel)
    }
  }
}
</script>
```

> **`AppWindow.vue` needs no change** — its `theApp` already prefers `this.params?.params?.workspace` and falls back to `app`, so once the registry stops re-labelling the key it resolves `workspace.path` correctly and URL persistence (`tabId`) resumes.

---

## Verification

| Check | Expected |
|---|---|
| Tab label after opening a workspace | Shows **`workspace.name`** (not blank, not `"Workspace"`) |
| `AppWindow` iframe URL | Resolves to **`workspace.path`** |
| Navigate inside workspace → reload | Panel restores `lastUrl` (proves `tabId` now resolves) |
| Open two different workspaces | Two distinct panels (`workspace-<key>`), correct labels |
| Chat opened with workspace context | Tab prefers `chat.name`, workspace still in params (unchanged) |

## Anti-pattern flagged

- ❌ **A registry that renames a payload key** (`workspace` → `app`). Payload keys are a contract between producer, registry, and reader — renaming them in the middle silently breaks every reader that follows the convention. Keep the semantic key identical end-to-end.

